// Probe: normal-map convention check for the world material. One big dome (height field, OpenGL-style normal map
// generated by heightToNormalLayer: +x = right = +u, +y = image-up = +v after row flip) on quads with different
// orientations (face built with GeomBuilder.quad: U = N x V). Light from the +V side => a RAISED dome is brighter on
// its +V half; light from the +U side => brighter on its +U half.
import { Engine, Scene, Vector3, Color4, FreeCamera, Camera, DirectionalLight, Mesh, VertexData, PBRMaterial, Matrix } from "@babylonjs/core";
import { WorldMaterialPlugin, createTextureArray } from "./render-materials-worldmat.ts";
import { heightToNormalLayer, GeomBuilder, type SurfAttrs, type V3 } from "./render-materials-proctex.ts";

const cross = (a: V3, b: V3): V3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];

export async function probe() {
  const canvas = document.getElementById("renderCanvas") as HTMLCanvasElement;
  const engine = new Engine(canvas, true, { preserveDrawingBuffer: true });
  const scene = new Scene(engine);
  scene.clearColor = new Color4(0, 0, 0, 1);
  const size = 64;
  const h = new Float32Array(size * size);
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
    const r = Math.hypot(x - size / 2 + 0.5, y - size / 2 + 0.5) / (size * 0.4);
    h[y * size + x] = r < 1 ? Math.sqrt(1 - r * r) * 20 : 0;
  }
  const flat = new Uint8Array(size * size * 4).fill(255);
  const albedo = createTextureArray(scene, [flat], size, { mipmaps: false });
  const nflat = new Uint8Array(size * size * 4);
  for (let i = 0; i < nflat.length; i += 4) nflat.set([128, 128, 255, 255], i);
  const normal = createTextureArray(scene, [nflat, heightToNormalLayer(h, size, 1.0)], size, { mipmaps: false });
  const mat = new PBRMaterial("w", scene);
  mat.metallic = 0;
  mat.roughness = 1;
  new WorldMaterialPlugin(mat).setTextures(albedo, normal);
  const sun = new DirectionalLight("sun", new Vector3(0, -1, 0), scene);
  sun.intensity = 3;
  const cam = new FreeCamera("cam", new Vector3(0, 0, -100), scene);
  cam.mode = Camera.ORTHOGRAPHIC_CAMERA;
  cam.maxZ = 6000;
  const a = engine.getRenderWidth() / engine.getRenderHeight();
  cam.orthoTop = 1.2; cam.orthoBottom = -1.2; cam.orthoLeft = -1.2 * a; cam.orthoRight = 1.2 * a;
  const W = engine.getRenderWidth(), H = engine.getRenderHeight();
  const S: SurfAttrs = { layer: 0, normalLayer: 1, rough: 1, emissive: 0, tint: [0.6, 0.6, 0.6], metal: 0, worldSize: 2 };

  const cases: Array<[string, V3, V3]> = [
    ["wall facing -Z (towards default camera)", [0, 0, -1], [0, 1, 0]],
    ["wall facing +X", [1, 0, 0], [0, 1, 0]],
    ["floor facing +Y (V = +Z)", [0, 1, 0], [0, 0, 1]],
    ["ceiling facing -Y (V = +X)", [0, -1, 0], [1, 0, 0]],
  ];
  const results: Record<string, unknown> = {};
  for (const [name, N, V] of cases) {
    const U = cross(N, V);
    const g = new GeomBuilder();
    // centre chosen so that uv (= p.U/2, p.V/2) spans exactly 0..1 over the quad
    const c: V3 = [U[0] + V[0], U[1] + V[1], U[2] + V[2]];
    g.quad(c, N, V, 1, 1, S);
    const mesh = new Mesh("q", scene);
    const vd = new VertexData();
    vd.positions = g.positions; vd.normals = g.normals; vd.uvs = g.uvs; vd.colors = g.colors; vd.indices = g.indices;
    vd.applyToMesh(mesh);
    mesh.setVerticesData("surf", g.surf, false, 4);
    mesh.material = mat;
    cam.position = new Vector3(c[0] + N[0] * 3000, c[1] + N[1] * 3000, c[2] + N[2] * 3000);
    cam.upVector = new Vector3(...V);
    cam.setTarget(new Vector3(...c));
    await scene.whenReadyAsync();
    const lum = async (p: V3) => {
      scene.render();
      const sp = Vector3.Project(new Vector3(...p), Matrix.Identity(), scene.getTransformMatrix(), cam.viewport.toGlobal(W, H));
      const d = (await engine.readPixels(Math.round(sp.x), Math.round(H - sp.y), 1, 1)) as Uint8Array;
      return d[0];
    };
    const at = (du: number, dv: number): V3 => [c[0] + U[0] * du + V[0] * dv, c[1] + U[1] * du + V[1] * dv, c[2] + U[2] * du + V[2] * dv];
    // light coming FROM +V (travelling -V) and from the front
    sun.direction = new Vector3(-V[0] - N[0] * 0.6, -V[1] - N[1] * 0.6, -V[2] - N[2] * 0.6).normalize();
    const vPlus = await lum(at(0, 0.45)), vMinus = await lum(at(0, -0.45));
    // light coming FROM +U
    sun.direction = new Vector3(-U[0] - N[0] * 0.6, -U[1] - N[1] * 0.6, -U[2] - N[2] * 0.6).normalize();
    const uPlus = await lum(at(0.45, 0)), uMinus = await lum(at(-0.45, 0));
    results[name] = { lightFromPlusV: { plusVHalf: vPlus, minusVHalf: vMinus }, lightFromPlusU: { plusUHalf: uPlus, minusUHalf: uMinus }, verdict: vPlus > vMinus && uPlus > uMinus ? "RAISED" : "INVERTED" };
    mesh.dispose();
  }
  engine.runRenderLoop(() => scene.render());
  return results;
}
